---level3 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl3_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end					game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		if dialog.show("Level3-1", faceDeyi) ==1 then break end		sound.play("60-4")		camera.setFollowRoleMode(false)		camera.gotoPosition(661,1395)		if dialog.show("Level3-2", faceJingya) ==1 then break end		if dialog.show("Level3-3", faceZhoumei) ==1 then break end		camera.gotoRole()		camera.setFollowRoleMode(true)		sound.play("58-1")		if dialog.show("Level3-4", faceShengqi) ==1 then break end		sound.play("57-1")		if dialog.show("Level2-8", faceWunai,2.5) ==1 then break end		game.setUserInputEnabled(true)				--set story viewed flag        global.setBool("lvl3_b1")		game.restartTiming()		role.setIdleActionEnabled(true)		isPlayingDemo = false		isSkip = false		until trueendif isSkip then	camera.gotoRole()	camera.setFollowRoleMode(true)	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()endonRoleDied = function()    countFail = countFail + 1    game.setUserInputEnabled(false)    if countFail <= 1 then		sound.play("51-2")        dialog.show("Level1-12", faceBujie)    else		sound.play("58-1")        dialog.show("Level1-13", faceShengqi)    end    game.setUserInputEnabled(true)    role.loadState()end